// ── Types ────────────────────────────────────────────────────────────────────────────────────────────────────────────

type DurationLevel = 'days' | 'hrs' | 'mins' | 'secs' | 'ms';
type DurationLevelTuple = [DurationLevel, number, (n: number) => string];

// ── Constants ────────────────────────────────────────────────────────────────────────────────────────────────────────

const DURATION_LEVELS: DurationLevelTuple[] = [
    ['days', 86_400_000, (n: number): string => (n === 1 ? '1 day' : `${formatNumberAsWholeNumber(n)} days`)],
    ['hrs', 3_600_000, (n: number): string => (n === 1 ? '1 hr' : `${formatNumberAsWholeNumber(n)} hrs`)],
    ['mins', 60_000, (n: number): string => (n === 1 ? '1 min' : `${formatNumberAsWholeNumber(n)} mins`)],
    ['secs', 1000, (n: number): string => (n === 1 ? '1 sec' : `${formatNumberAsWholeNumber(n)} secs`)],
    ['ms', 0, (n: number): string => `${formatNumberAsWholeNumber(n)} ms`]
];

const NUMBER_FORMATTER_DEFAULT_LOCALE = 'en';
const NUMBER_FORMATTER_MAP = new Map<string, Intl.NumberFormat>();

// ── Actions - Data Type Conversion ───────────────────────────────────────────────────────────────────────────────────

// See: https://www.odata.org/documentation/odata-version-2-0/overview/.
export function convertODataTypeIdToUsageTypeId(oDataTypeId: string): string {
    switch (oDataTypeId) {
        case 'Edm.Binary':
            return 'unknown'; // Binary...
        case 'Edm.Boolean':
            return 'boolean';
        case 'Edm.Byte':
            return 'wholeNumber';
        case 'Edm.DateTime':
            return 'moment'; // DateTime...
        case 'Edm.DateTimeOffset':
            return 'moment'; // DateTimeOffset...
        case 'Edm.Decimal':
            return 'decimalNumber';
        case 'Edm.Double':
            return 'decimalNumber';
        case 'Edm.Guid':
            return 'string';
        case 'Edm.Int16':
            return 'wholeNumber';
        case 'Edm.Int32':
            return 'wholeNumber';
        case 'Edm.Int64':
            return 'wholeNumber';
        case 'Edm.SByte':
            return 'wholeNumber';
        case 'Edm.Single':
            return 'decimalNumber';
        case 'Edm.String':
            return 'string';
        case 'Edm.Time':
            return 'momentTime'; // Time...
        default:
            return 'unknown';
    }
}

// ── Actions - File Path Segment Extraction ───────────────────────────────────────────────────────────────────────────

// Extract the path without its final basename extension.
// Dots in parent directories are ignored, and leading dots in the basename
// are treated as part of dotfile names rather than as an extension separator.
export function extractNameFromPath(itemPath: string): string | undefined {
    if (itemPath) {
        const lastSeparatorIndex = itemPath.lastIndexOf('/');
        const basenameStartIndex = lastSeparatorIndex + 1;
        const lastExtensionIndex = itemPath.lastIndexOf('.');
        if (lastExtensionIndex <= basenameStartIndex) return itemPath;
        return lastExtensionIndex === -1 ? itemPath : itemPath.slice(0, Math.max(0, lastExtensionIndex));
    }
    return undefined;
}

// Extract only the final basename extension.
// Returns undefined when the basename has no extension, including dotfiles such
// as .gitignore where the only dot is the leading character of the basename.
export function extractExtensionFromPath(itemPath: string): string | undefined {
    if (itemPath) {
        const lastSeparatorIndex = itemPath.lastIndexOf('/');
        const basenameStartIndex = lastSeparatorIndex + 1;
        const lastExtensionIndex = itemPath.lastIndexOf('.');
        if (lastExtensionIndex <= basenameStartIndex) return undefined;
        if (lastExtensionIndex !== -1) return itemPath.slice(Math.max(0, lastExtensionIndex + 1));
    }
    return undefined;
}

// ── Actions - String Formatting ──────────────────────────────────────────────────────────────────────────────────────

export function formatNumberAsDecimalNumber(number?: number, decimalPlaces = 2, minimumFractionDigits = decimalPlaces, locale = NUMBER_FORMATTER_DEFAULT_LOCALE): string {
    if (number == null) return '';
    const formatterId = `${locale}decimal${String(decimalPlaces)}.${String(minimumFractionDigits)}`;
    let numberFormatter = NUMBER_FORMATTER_MAP.get(formatterId);
    if (!numberFormatter) {
        numberFormatter = new Intl.NumberFormat(locale, {
            localeMatcher: 'best fit',
            maximumFractionDigits: decimalPlaces,
            minimumFractionDigits,
            minimumIntegerDigits: 1,
            style: 'decimal',
            useGrouping: true
        });
        NUMBER_FORMATTER_MAP.set(formatterId, numberFormatter);
    }
    return numberFormatter.format(number);
}

export function formatNumberAsSize(number?: number, decimalPlaces = 1): string {
    if (number == null) return '';
    if (number < 1000) return formatNumberAsWholeNumber(number);
    if (number < 1_000_000) return `${formatNumberAsDecimalNumber(number / 1000, decimalPlaces, 0)}K`;
    if (number < 1_000_000_000) return `${formatNumberAsDecimalNumber(number / 1_000_000, decimalPlaces, 0)}M`;
    return number < 1_000_000_000_000
        ? `${formatNumberAsDecimalNumber(number / 1_000_000_000, decimalPlaces, 0)}B`
        : `${formatNumberAsDecimalNumber(number / 1_000_000_000_000, decimalPlaces, 0)}T`;
}

export function formatNumberAsStorageSize(number?: number, decimalPlaces = 1): string {
    if (number == null) return '';
    if (number === 1) return '1 byte';
    if (number < 1024) return `${formatNumberAsWholeNumber(number)} bytes`;
    if (number < 1_048_576) return `${formatNumberAsDecimalNumber(number / 1024, decimalPlaces, 0)} KB`;
    if (number < 1_073_741_824) return `${formatNumberAsDecimalNumber(number / 1_048_576, decimalPlaces, 0)} MB`;
    return number < 1_099_511_627_776
        ? `${formatNumberAsDecimalNumber(number / 1_073_741_824, decimalPlaces, 0)} GB`
        : `${formatNumberAsDecimalNumber(number / 1_099_511_627_776, decimalPlaces, 0)} TB`;
}

export function formatNumberAsDuration(number?: number, stopAt: DurationLevel = 'ms'): string {
    if (number == null) return '';

    // Start at the largest unit the value actually fills, so a value below the requested level still reads sensibly
    // rather than as a run of zeroes.
    const startIndex = DURATION_LEVELS.findIndex(([, threshold]) => number >= threshold);
    const firstIndex = startIndex === -1 ? DURATION_LEVELS.length - 1 : startIndex;
    const stopIndex = DURATION_LEVELS.findIndex(([level]) => level === stopAt);

    const durationLevels = DURATION_LEVELS.slice(firstIndex, Math.max(stopIndex, firstIndex) + 1);
    const parts: string[] = [];
    let remaining = number;
    for (const [, threshold, format] of durationLevels) {
        if (remaining < threshold || (remaining === 0 && parts.length > 0)) continue;
        parts.push(format(threshold > 0 ? Math.floor(remaining / threshold) : remaining));
        remaining %= threshold > 0 ? threshold : 1;
    }
    return parts.join(' ');
}

export function formatNumberAsWholeNumber(number?: number, locale = NUMBER_FORMATTER_DEFAULT_LOCALE): string {
    if (number == null) return '';
    const formatterId = `${locale}decimal0.0`;
    let numberFormatter = NUMBER_FORMATTER_MAP.get(formatterId);
    if (!numberFormatter) {
        numberFormatter = new Intl.NumberFormat(locale, {
            localeMatcher: 'best fit',
            maximumFractionDigits: 0,
            minimumFractionDigits: 0,
            minimumIntegerDigits: 1,
            style: 'decimal',
            useGrouping: true
        });
        NUMBER_FORMATTER_MAP.set(formatterId, numberFormatter);
    }
    return numberFormatter.format(number);
}

// ── Actions - Lookup ─────────────────────────────────────────────────────────────────────────────────────────────────

export function lookupMimeTypeForExtension(extension?: string): string {
    // Extensions arrive from file names as typed, so 'REPORT.CSV' must resolve the same as 'report.csv'.
    switch (extension?.toLowerCase()) {
        case 'csv':
            return 'text/csv';
        case 'tab':
        case 'tsv':
            return 'text/tab-separated-values';
        case 'xls':
            return 'application/vnd.ms-excel';
        case 'xlsx':
            return 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet';
        default:
            return 'application/octet-stream';
    }
}

